-- Fichier généré par scripts/generate_data.py — ne pas modifier à la main.
CREATE SCHEMA IF NOT EXISTS iceberg.banque WITH (location = 's3://warehouse/banque');

DROP TABLE IF EXISTS iceberg.banque.agences;
CREATE TABLE iceberg.banque.agences (
  agence_id INTEGER COMMENT 'Identifiant unique de l''agence (clé primaire).',
  nom_agence VARCHAR COMMENT 'Nom commercial de l''agence.',
  ville VARCHAR COMMENT 'Ville où se situe l''agence.',
  region VARCHAR COMMENT 'Région administrative du Maroc où se situe l''agence (ex. Casablanca-Settat, Rabat-Salé-Kénitra, Marrakech-Safi).'
)
COMMENT 'Réseau d''agences de la banque (une ligne par agence).'
WITH (format = 'PARQUET');

DROP TABLE IF EXISTS iceberg.banque.clients;
CREATE TABLE iceberg.banque.clients (
  client_id INTEGER COMMENT 'Identifiant unique du client (clé primaire).',
  nom VARCHAR COMMENT 'Nom de famille du client, ou raison sociale pour une entreprise.',
  prenom VARCHAR COMMENT 'Prénom du client (vide pour le segment Entreprise).',
  segment VARCHAR COMMENT 'Segment commercial du client : Particulier, Professionnel ou Entreprise.',
  date_entree DATE COMMENT 'Date d''entrée en relation avec la banque.',
  agence_id INTEGER COMMENT 'Agence de rattachement du client (référence agences.agence_id).',
  ville VARCHAR COMMENT 'Ville de résidence du client.',
  revenu_mensuel DECIMAL(14,2) COMMENT 'Revenu mensuel déclaré (chiffre d''affaires mensuel pour une entreprise), en MAD.'
)
COMMENT 'Référentiel des clients de la banque (une ligne par client).'
WITH (format = 'PARQUET');

DROP TABLE IF EXISTS iceberg.banque.comptes;
CREATE TABLE iceberg.banque.comptes (
  compte_id INTEGER COMMENT 'Identifiant unique du compte (clé primaire).',
  client_id INTEGER COMMENT 'Client titulaire du compte (référence clients.client_id).',
  type_compte VARCHAR COMMENT 'Type de compte : Courant, Epargne ou Devises.',
  devise VARCHAR COMMENT 'Devise de tenue du compte : MAD, EUR ou USD.',
  date_ouverture DATE COMMENT 'Date d''ouverture du compte.',
  solde DECIMAL(16,2) COMMENT 'Solde du compte à la date de référence, en MAD (contre-valeur pour les comptes en devises).',
  statut VARCHAR COMMENT 'Statut du compte : Actif, Dormant ou Clôturé.'
)
COMMENT 'Comptes bancaires détenus par les clients (une ligne par compte).'
WITH (format = 'PARQUET');

DROP TABLE IF EXISTS iceberg.banque.transactions;
CREATE TABLE iceberg.banque.transactions (
  transaction_id BIGINT COMMENT 'Identifiant unique de l''opération (clé primaire).',
  compte_id INTEGER COMMENT 'Compte mouvementé (référence comptes.compte_id).',
  date_operation DATE COMMENT 'Date de l''opération.',
  montant DECIMAL(14,2) COMMENT 'Montant de l''opération en MAD, toujours positif (le sens est porté par la colonne sens).',
  sens VARCHAR COMMENT 'Sens de l''opération : CREDIT (entrée d''argent sur le compte) ou DEBIT (sortie d''argent).',
  canal VARCHAR COMMENT 'Canal utilisé : Agence, GAB, Mobile, Web ou Virement.',
  categorie VARCHAR COMMENT 'Nature de l''opération : Salaire, Virement reçu, Versement espèces, Retrait espèces, Paiement facture, Achat, Virement émis, Remboursement crédit ou Frais bancaires.'
)
COMMENT 'Opérations enregistrées sur les comptes, de janvier 2025 à octobre 2026 (une ligne par opération).'
WITH (format = 'PARQUET', partitioning = ARRAY['month(date_operation)']);

DROP TABLE IF EXISTS iceberg.banque.credits;
CREATE TABLE iceberg.banque.credits (
  credit_id INTEGER COMMENT 'Identifiant unique du crédit (clé primaire).',
  client_id INTEGER COMMENT 'Client emprunteur (référence clients.client_id).',
  type_credit VARCHAR COMMENT 'Type de crédit : Immobilier, Consommation, Auto ou Equipement.',
  montant_accorde DECIMAL(14,2) COMMENT 'Montant initial accordé, en MAD.',
  taux_annuel DECIMAL(5,2) COMMENT 'Taux d''intérêt annuel, en pourcentage (ex. 4.75 signifie 4,75 %).',
  duree_mois INTEGER COMMENT 'Durée contractuelle du crédit, en mois.',
  date_octroi DATE COMMENT 'Date d''octroi (déblocage) du crédit.',
  encours DECIMAL(14,2) COMMENT 'Capital restant dû à la date de référence, en MAD.',
  statut VARCHAR COMMENT 'Qualité du crédit : Sain, Impayé ou Contentieux.'
)
COMMENT 'Crédits accordés aux clients (une ligne par crédit).'
WITH (format = 'PARQUET');
